import '../scripts/prepare-reports.mjs';
import {boot} from './ui-test-harness.mjs';
import {prepareEncounter} from './encounter-test-fixture.mjs';
import fs from 'node:fs';
import assert from 'node:assert/strict';
import {replayFrame} from '../dist/src/playback.js';
const html=fs.readFileSync('dist/sbr-race.html','utf8'),js=html.match(/<script type="module">([\s\S]*?)<\/script>/)[1];
const checks=[];
function test(n,f){try{f();checks.push({n,ok:true});}catch(e){checks.push({n,ok:false,error:e.stack});}}

function battle(b,win=false){
 const r=b.ui.race;r.state.mode='encounter';r.state.encounter='johnny';b.ui.action('encounter:fight');const C=r.state.combat;
 C.P.hp=C.P.maxHp=1000;C.P.atk=300;C.P.dmgB=win?100:0;C.E.hp=win?1:1000;C.E.maxHp=1000;C.E.eva=-100;
 C.P.hand=['sbr_steel_throw'];C.P.light=3;C.ePlan=[];b.ui.action('select:0');b.ui.action('resolve');return C;
}
test('새 사건은 페이지 맨 위에서 표시·카드 선택과 메뉴 확인은 스크롤 유지',()=>{
 const b=boot();assert.equal(b.scrolls.length,0);b.ui.action('roll-birth');assert.equal(b.scrolls.length,0);b.ui.action('start');assert(b.scrolls.length>0);
 const r=b.ui.race;r.state.tick=1;r.state.mode='event';r.state.event='junction_1';b.ui.render();const before=b.scrolls.length;b.ui.action('deck');b.close();assert.equal(b.scrolls.length,before);b.ui.action('event:0');assert(b.scrolls.length>before);assert.equal(b.scrolls.at(-1).top,0);
 r.state.mode='encounter';r.state.encounter='johnny';b.ui.action('encounter:fight');const combat=b.scrolls.length;b.ui.action('select:0');assert.equal(b.scrolls.length,combat);
});
test('직전 결과는 스크롤 영역 밖·현재 사건과 갈림길 선택 유지',()=>{const b=boot();for(const boss of b.ui.data.hiddenBosses)boss.chance=0;for(const row of b.ui.data.encounterRules.namedChances)row.chance=0;assert.equal((b.text().match(/class="birth-row"/g)||[]).length,4);const chosen=structuredClone(b.ui.draft);b.ui.action('start');assert.deepEqual(b.ui.race.state.birth,chosen);const r=b.ui.race;assert.equal(r.state.mode,'event');assert(!b.text().includes('출발 기록'));assert(!b.text().includes('next-route'));assert(!b.text().includes('다음 여정을 이어 간다'));r.state.mode='event';r.state.event='town_clinic';r.state.ch.money=0;b.ui.action('event:2');assert.equal(r.state.tick,1);assert(b.text().includes('aria-label="사건 결과"'));assert(b.text().indexOf('class="previous-outcome"')<b.text().indexOf('class="journey-body"'));assert(b.text().indexOf('class="journey-body"')<b.text().indexOf('aria-label="현재 사건"'));assert.equal((b.text().match(/class="previous-outcome"/g)||[]).length,1);r.state.usedEvents.push('stand_palm');r.state.mode='event';r.state.event='junction_1';r.state.ch.money=6;r.state.ch.hp=Math.max(1,r.state.ch.hp-20);b.ui.action('event:2');assert.equal(r.state.tick,2);assert(b.ui.data.events.find(x=>x.id===r.state.event).where.includes('town'));assert(!b.text().includes('<select'));});

test('기본 연출·실제 판정 순서·결과 전 HP 유지·중복 입력 차단',()=>{
 const b=boot();b.ui.action('start');battle(b);const r=b.ui.race,p=r.state.playback;assert(p);assert(b.text().includes('연출 재생 중'));assert.equal(replayFrame(p).E.hp,1000);
 const committed=JSON.stringify(r.state.combat);b.ui.action('resolve');b.ui.action('select:0');assert.equal(JSON.stringify(r.state.combat),committed);
 while(p.events[p.cursor].k!=='atk')b.step();assert.equal(p.phase,'announce');const previous=replayFrame(p).E.hp;b.step();assert.equal(p.phase,'roll');assert.equal(replayFrame(p).E.hp,previous);assert(b.text().includes('판정 중'));b.step();assert.equal(p.phase,'result');assert.equal(replayFrame(p).E.hp,p.events[p.cursor].snap.E.hp);assert(b.text().includes(String(p.events[p.cursor].ra)));
 let guard=200;while(r.state.playback&&guard--)b.step();assert(guard>0);assert.equal(r.state.combat.round,2);assert(!b.text().includes('연출 재생 중'));
});
test('설정 창과 백그라운드에서는 재생 정지·닫거나 복귀하면 재개',()=>{
 const b=boot();b.ui.action('start');battle(b);b.ui.action('settings');assert.equal(b.timers.size,0);const cursor=b.ui.race.state.playback.cursor;b.ui.action('speed:fast');assert.equal(b.timers.size,0);b.close();assert.equal(b.timers.size,1);assert([...b.timers.values()][0].ms<350);b.document.hidden=true;b.ui.render();assert.equal(b.timers.size,0);assert.equal(b.ui.race.state.playback.cursor,cursor);b.document.hidden=false;b.ui.render();assert.equal(b.timers.size,1);
});
test('재생 중 새로고침은 저장된 위치·판정·손패·적 행동을 그대로 복원',()=>{
 const b=boot();b.ui.action('start');battle(b);b.step();b.step();const saved=JSON.parse(b.storage.get('sbr-race-v04'));const b2=boot(new Map(b.storage));b2.ui.action('continue');assert.deepEqual(b2.ui.race.state.playback,saved.playback);assert.deepEqual(b2.ui.race.state.combat.ePlan,saved.combat.ePlan);assert.deepEqual(b2.ui.race.state.combat.P.hand,saved.combat.P.hand);assert.equal(b2.timers.size,1);
});
test('마지막 타격까지 보상을 숨기고 완료 후 보상·환전·다음 사건을 한 번만 처리',()=>{
 const b=boot();b.ui.action('start');battle(b,true);const r=b.ui.race;assert.equal(r.state.mode,'reward');assert(r.state.playback);assert(!b.text().includes('대결 뒤에 남은 것'));const cash=r.state.ch.money;assert(!r.reward('cash'));b.ui.action('cash-card');assert.equal(r.state.ch.money,cash);let guard=200;while(r.state.playback&&guard--)b.step();assert(b.text().includes('대결 뒤에 남은 것'));b.ui.action('cash-card');assert.equal(r.state.ch.money,cash+10);assert.equal(r.state.tick,1);assert(['event','encounter','omen'].includes(r.state.mode));
});
test('설정에서만 생략·설정 유지·재생 종료 시 이중 계산과 중복 보상 없음',()=>{
 const b=boot();b.ui.action('start');battle(b);const r=b.ui.race,committed=JSON.stringify(r.state.combat);b.ui.action('settings');b.ui.action('speed:off');assert(!r.state.playback);assert.equal(JSON.stringify(r.state.combat),committed);assert.equal(b.timers.size,0);b.close();const b2=boot(new Map(b.storage));b2.ui.action('continue');battle(b2);assert(!b2.ui.race.state.playback);assert.equal(b2.ui.race.state.combat.round,2);
});
test('사건 선택지의 표시 확률은 현재 능력치 변화에 즉시 반영',()=>{const b=boot();b.ui.action('start');b.ui.race.state.mode='event';b.ui.race.state.event='camp_practice';b.ui.race.state.ch.stats.atk=24;b.ui.render();assert(b.text().includes('목표 30 · 성공 95%'));b.ui.race.state.ch.stats.atk=30;b.ui.render();assert(b.text().includes('성공 100%'));b.ui.action('help');assert(b.elements.get('#sheet-body').innerHTML.includes('1d100 + 해당 능력치가 목표치 이상이면 성공합니다.'));});
test('덱·영구 경험 직접 열기·키워드 설명·단일 파일 자동 저장',()=>{const b=boot();b.ui.action('start');assert(b.text().includes('data-action="relics"'));b.ui.action('relics');assert.equal(b.elements.get('#sheet-title').textContent,'경험');b.ui.action('deck');assert.equal(b.elements.get('#sheet-title').textContent,'나의 덱');b.ui.action('keywords');assert(b.elements.get('#sheet-body').innerHTML.includes('위축'));assert(b.storage.has('sbr-race-v04'));});
test('조건부 선택지는 숨기되 현재 조건을 충족하면 원래 선택 번호로 실행',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='event';r.state.event='talent_work';r.state.birth.talents='reflex';b.ui.render();assert(!b.text().includes('정밀한 손질을 도와준다'));assert(b.text().includes('data-action="event:1"'));r.state.birth.talents='steady';b.ui.render();assert(b.text().includes('정밀한 손질을 도와준다'));});
test('장비는 독립 메뉴에서 구입품 확인·장착·해제',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='event';r.state.event='shop_coat';r.state.ch.money=50;b.ui.action('event:0');assert(r.state.items.includes('coat'));b.ui.action('equipment');assert.equal(b.elements.get('#sheet-title').textContent,'장비');assert(b.elements.get('#sheet-body').innerHTML.includes('data-action="equip:coat"'));b.ui.action('equip:coat');assert.equal(r.state.equipment.armor,'coat');assert(b.elements.get('#sheet-body').innerHTML.includes('data-action="unequip:coat"'));});

test('생성된 무명 적의 의도·연출·저장 복원 화면 정상 표시',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='event';r.state.event='gunfire';b.ui.action('event:0');assert(r.state.encounter.includes('#'));assert(b.text().includes('참가자'));b.ui.action('resolve');assert(r.state.playback);assert(b.text().includes('연출 재생 중'));const b2=boot(new Map(b.storage));b2.ui.action('continue');assert(b2.text().includes('참가자'));assert(b2.ui.race.state.playback);});
test('기술 시험은 실제 적중 연출 후 공용 사건으로 이어지며 완성은 후반까지 대기',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.origin='steel';r.state.tick=24;r.state.usedEvents.push('stand_palm');r.state.ch.flags.story_steel_1=true;r.state.mode='event';r.state.event='origin_steel_2';b.ui.action('event:0');const C=r.state.combat;C.P.hp=C.P.maxHp=1000;C.E.hp=C.E.maxHp=1000;for(let turn=0;turn<2;turn++){C.ePlan=[];C.P.hand=['sbr_steel_throw'];C.P.light=3;C.P.atk=300;C.E.eva=-300;b.ui.action('select:0');b.ui.action('resolve');let guard=100;while(r.state.playback&&guard--)b.step();assert(guard>0);}assert.equal(r.state.mode,'event');assert.notEqual(r.state.event,'origin_steel_3');assert(b.text().includes('시험을 통과했다.'));assert(b.text().includes('aria-label="전투 결과"'));r.state.tick=48;r.state.mode='travel';r.state.economy.market.nextTick=1000;b.ui.render();assert.equal(r.state.event,'origin_steel_3');b.ui.action('event:0');assert(r.lockedDeck());assert(r.state.items.includes('lesson_steel'));});
test('3개·4개 사건 선택지는 추천색 없이 모두 표시하고 원래 번호를 유지',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;for(const [id,n]of [['camp_wind',3],['river',4]]){r.state.mode='event';r.state.event=id;r.state.ch.money=100;b.ui.render();assert(b.text().includes('data-count="'+n+'"'));const buttons=[...b.text().matchAll(/<button[^>]*data-action="event:(\d+)"[^>]*>/g)];assert.equal(buttons.length,n);assert.deepEqual(buttons.map(x=>+x[1]),Array.from({length:n},(_,i)=>i));assert(buttons.every(x=>!x[0].includes('primary')));}});
test('네 번째 선택도 별도 결과로 실행하고 한 행동만 소비',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='event';r.state.event='river';r.state.ch.stats.atk=100;const tick=r.state.tick;b.ui.action('event:3');assert.equal(r.state.tick,tick+1);assert(r.state.previousOutcome.text.includes('밧줄을 잡고'));assert.equal(r.state.previousOutcome.check.stat,'atk');});
test('추가 유료 선택의 자금 부족 차단과 실제 차감·후속 조건 반영',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='event';r.state.event='camp_meal';r.state.ch.money=0;const tick=r.state.tick;b.ui.render();assert(/<button[^>]*data-action="event:3"[^>]*disabled/.test(b.text()));b.ui.action('event:3');assert.equal(r.state.tick,tick);r.state.ch.money=8;b.ui.action('event:3');assert.equal(r.state.ch.money,0);assert.equal(r.state.tick,tick+1);assert(r.state.ch.flags.heard_warning);});
test('덱은 중복도 카드별 표시·각 카드 효과와 조작을 바로 제공',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.ch.deck=['sbr_basic_strike','sbr_basic_strike','sbr_basic_guard','sbr_basic_cut','sbr_basic_rush'];r.state.ch.side=['sbr_enemy_johnny','sbr_enemy_johnny'];r.state.origin='ranch';b.ui.action('deck');const h=b.elements.get('#sheet-body').innerHTML;assert(h.includes('장착 5장')&&h.includes('최대 12장'));assert.equal((h.match(/data-card-id="sbr_basic_strike"/g)||[]).length,2);assert.equal((h.match(/data-card-id="sbr_enemy_johnny"/g)||[]).length,2);assert.equal((h.split(b.ui.data.cards.sbr_enemy_johnny.d).length-1),2);assert(!h.includes('deck-info:'));assert(!h.includes('deck-detail'));assert(!h.includes('<small>2장</small>'));b.ui.action('insert:0');assert.equal(r.state.ch.deck.length,6);assert.equal(r.state.ch.side.length,1);b.ui.action('remove:5');assert.equal(r.state.ch.deck.length,5);b.ui.action('remove:0');assert.equal(r.state.ch.deck.length,4);b.ui.action('remove:0');assert.equal(r.state.ch.deck.length,4);});

test('5장·12장 덱은 같은 창에서 장수를 유지하며 즉시 교체',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.origin='ranch';r.state.ch.deck=Array(5).fill('sbr_basic_strike');r.state.ch.side=['sbr_enemy_johnny'];b.ui.action('deck');assert(b.elements.get('#sheet-body').innerHTML.includes('data-action="swap-pick:0"'));b.ui.action('swap-pick:0');assert(b.elements.get('#sheet-body').innerHTML.includes('data-action="swap-with:0"'));b.ui.action('swap-with:0');assert.equal(r.state.ch.deck.length,5);assert.equal(r.state.ch.deck[0],'sbr_enemy_johnny');assert.equal(r.state.ch.side[0],'sbr_basic_strike');while(r.state.ch.deck.length<12)r.state.ch.deck.push('sbr_basic_strike');b.ui.action('deck');b.ui.action('swap-pick:0');b.ui.action('swap-with:0');assert.equal(r.state.ch.deck.length,12);assert.equal(r.state.ch.deck[0],'sbr_basic_strike');assert.equal(r.state.ch.side[0],'sbr_enemy_johnny');});
test('덱 조작은 대화상자 한 곳의 스크롤 유지·교체 취소는 소유 변경 없음',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.ch.side=['sbr_enemy_johnny'];b.ui.action('deck');const dialog=b.elements.get('#sheet');dialog.scrollTop=120;b.ui.action('swap-pick:0');assert.equal(dialog.scrollTop,120);const before=JSON.stringify([r.state.ch.deck,r.state.ch.side]);b.ui.action('swap-cancel');assert.equal(JSON.stringify([r.state.ch.deck,r.state.ch.side]),before);assert.equal(dialog.scrollTop,120);});

test('전투 보상에서 짧은 덱을 유지하고 카드를 보관하는 선택 표시·실행',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.origin='ranch';r.state.mode='reward';r.state.encounter='johnny';r.state.offer='sbr_enemy_johnny';b.ui.render();assert(b.text().includes('data-action="store-card"'));const deck=r.state.ch.deck.slice();b.ui.action('store-card');assert.deepEqual(r.state.ch.deck,deck);assert(r.state.ch.side.includes('sbr_enemy_johnny'));});
test('상시 보급 메뉴 없음·주기적 상단 사건에서 구매·장착·스크롤 유지',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.ch.money=100;assert(!b.text().includes('data-action="shop"'));b.ui.action('shop');b.ui.action('shop-tab:gear');assert(!b.elements.get('#sheet').open);r.state.usedEvents.push('stand_palm','stand_echo');r.state.mode='travel';r.state.tick=4;r.state.nextTravel='rest';b.ui.render();assert(r.canShop());assert(b.text().includes('data-action="shop"'));assert(b.text().includes('방문·거래·출발 시 행동 소모 없음'));assert(!b.text().match(/<footer[^>]*>[\s\S]*?data-action="shop"/));b.ui.action('shop');assert.equal(b.elements.get('#sheet-title').textContent,'SBR 대회 보급소');assert(!b.elements.get('#sheet-body').innerHTML.includes('훈련'));const dialog=b.elements.get('#sheet');dialog.scrollTop=180;b.ui.action('buy:gear_coat');assert.equal(r.state.equipment.armor,'coat');assert.equal(r.state.tick,4);assert.equal(dialog.scrollTop,180);assert(!b.elements.get('#sheet-body').innerHTML.includes('data-item="gear_coat"'));assert(b.elements.get('#sheet-body').innerHTML.includes(b.ui.data.items.coat.n+' 구매·장착'));b.close();b.ui.action('event:0');assert(!r.canShop());assert.equal(r.state.tick,4);assert(b.ui.data.events.find(x=>x.id===r.state.event).where.includes('camp'));});
test('전용 덱의 카드 구매·최대 체력 치료는 비용과 불가 사유를 표시',()=>{const b=boot();b.ui.draft.origins='steel';b.ui.action('start');const r=b.ui.race;r.state.mode='event';r.state.event='town_clinic';b.ui.render();assert(b.text().includes('전용 덱은 일반 카드를 구입하지 않습니다.'));assert(b.text().includes('현재 받을 수 있는 효과가 없습니다.'));const cash=r.state.ch.money;b.ui.action('event:1');assert.equal(r.state.ch.money,cash);assert.equal(r.state.tick,0);});
test('전용 덱 승리는 연출 후 보상 선택 없이 자동 환전·다음 사건 진행',()=>{const b=boot();b.ui.draft.origins='steel';b.ui.action('start');const r=b.ui.race;const cash=r.state.ch.money;battle(b,true);assert(r.state.playback);assert.equal(r.state.mode,'travel');assert(!b.text().includes('data-action="store-card"'));let guard=200;while(r.state.playback&&guard--)b.step();assert(guard>0);assert.equal(r.state.mode,'event');assert.equal(r.state.tick,1);assert(r.state.ch.money>cash);assert.equal(r.state.ch.side.length,0);assert(b.text().includes('카드 보상 대신'));});
test('보급품은 전투 중 직접 사용·효과와 수량 갱신·턴당 하나만',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.ch.money=100;r.state.usedEvents.push('stand_palm','stand_echo');r.state.mode='travel';r.state.tick=4;assert(r.travel());assert(r.buy('supply_bandage'));assert(r.buy('supply_smoke'));r.state.mode='encounter';r.state.encounter='johnny';b.ui.action('encounter:fight');const C=r.state.combat;C.P.hp=20;const light=C.P.light;b.ui.render();assert(b.text().includes('data-action="supply:bandage"'));b.ui.action('supply:bandage');assert.equal(C.P.hp,38);assert.equal(C.P.light,light);assert.equal(r.state.economy.stock.bandage,0);b.ui.action('supply:smoke');assert.equal(r.state.economy.stock.smoke,1);assert.equal(r.state.tick,4);});
test('각성 재능 미리 보기·시작 후 스탠드와 사용 진척을 메인 화면에서 표시',()=>{const b=boot();b.ui.draft.talents='recovery';b.ui.render();assert(b.text().includes('스탠드 각성 · 파워형 스탠드'));assert(b.text().includes('시작 덱 4장 · 보관 3장'));b.ui.action('start');assert(b.text().includes('파워형 스탠드 · 발현'));assert(b.text().includes('전용기 0 / 5회'));});
test('일반 출발은 미각성·악마의 손바닥에서 선택하면 결과와 상태가 즉시 갱신',()=>{const b=boot();b.ui.action('start');assert(!b.text().includes('스탠드 미각성'));const r=b.ui.race;r.state.tick=8;r.state.event='stand_palm';r.state.mode='event';b.ui.render();assert(b.text().includes('악마의 손바닥'));assert(b.text().includes('data-count="4"'));b.ui.action('event:1');assert(b.text().includes('스피드형 스탠드 · 발현'));assert(b.text().includes('스탠드 각성 · 스피드형 스탠드'));assert.equal(r.state.ch.deck.length,4);assert.equal(r.state.ch.side.length,3);});
test('기본 스탠드 히든도 전용기를 해제해 4장 편성·창 재열기 시 보관 유지',()=>{const b=boot();b.ui.draft.origins='time';b.ui.action('start');b.ui.action('deck');const r=b.ui.race,i=r.state.ch.deck.findIndex(id=>b.ui.data.cards[id].stand),id=r.state.ch.deck[i],body=b.elements.get('#sheet-body').innerHTML;assert(!new RegExp('data-action="remove:'+i+'"[^>]*disabled').test(body));b.ui.action('remove:'+i);while(r.state.ch.deck.length>4)b.ui.action('remove:0');assert.equal(r.state.ch.deck.length,4);assert(r.state.ch.side.includes(id));assert(!r.state.ch.deck.includes(id));b.ui.action('deck');assert(r.state.ch.side.includes(id));});

test('턴 시작 연출에는 효과를 표시하고 행동 순서에는 같은 카드를 중복 표시하지 않음',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='encounter';r.state.encounter='johnny';b.ui.action('encounter:fight');const C=r.state.combat;C.P.hp=C.P.maxHp=C.E.hp=C.E.maxHp=10000;C.P.hand=['sbr_basic_step'];C.ePlan=[];b.ui.action('select:0');b.ui.action('resolve');assert.equal(r.state.playback.events[0].k,'turnStart');assert(b.text().includes('턴 시작 효과'));b.step();assert(b.text().includes('+20 이번 턴'));const order=b.text().match(/<div class="action-order"[\s\S]*?<\/div>/)?.[0];assert.equal((order.match(/나 · 가벼운 발놀림/g)||[]).length,1);});
test('구버전 회복 재능은 각성한 재능으로 표시하지 않고 기존 설명 보존',()=>{const b=boot();b.ui.action('start');const old=structuredClone(b.ui.race.state);old.birth.talents='recovery';old.birth.version=1;assert(b.ui.race.restore(old));b.ui.action('birth-record');const body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('빠른 회복'));assert(!body.includes('이미 각성한 정신'));assert(!b.ui.race.state.stand);b.ui.action('birth-detail:talents');assert(b.elements.get('#sheet-body').innerHTML.includes('턴마다 HP 회복 +1'));});
test('스탠드 영구 효과는 한국어 시점과 전투당 제한을 정확히 표시',()=>{const b=boot();b.ui.draft.talents='recovery';b.ui.action('start');b.ui.action('relics');const body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('전투 시작 시 기세 +2 (전투당 1회)'));assert(!body.includes('battleStart'));assert(!body.includes('roundStart'));});
test('각성 화면은 세 유형·보류와 이름·선택 대사를 한 화면에 표시',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.tick=8;r.state.mode='event';r.state.event='stand_palm';b.ui.render();for(const text of ['파워형','스피드형','특수능력형','지금은 안전한 길로'])assert(b.text().includes(text));assert(b.text().includes('id="awakening-stand-name"'));assert(b.text().includes('id="awakening-stand-line"'));b.input('awakening-stand-name','  푸른   길  ');b.input('awakening-stand-line','나의 길을 연다!');b.ui.action('event:2');assert.equal(r.state.stand.type,'special');assert.equal(r.state.stand.name,'푸른 길');assert.equal(r.state.stand.line,'나의 길을 연다!');assert(b.text().includes('푸른 길 · 특수능력형'));});
test('각성 이름 입력은 도움 창·새로고침 후에도 초안으로 유지',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.tick=8;r.state.mode='event';r.state.event='stand_palm';b.ui.render();b.input('awakening-stand-name','지평선');b.input('awakening-stand-line','앞으로!');b.ui.action('help');b.close();b.ui.render();assert(b.text().includes('value="지평선"'));const copy=boot(b.storage);copy.ui.action('continue');assert(copy.text().includes('value="지평선"'));assert(copy.text().includes('value="앞으로!"'));});
test('길이 초과 이름은 구체적 오류를 보이고 사건을 소비하지 않음',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.tick=8;r.state.mode='event';r.state.event='stand_palm';b.ui.render();b.input('awakening-stand-name','가'.repeat(21));const old=JSON.stringify(r.state);b.ui.action('event:0');assert.equal(JSON.stringify(r.state),old);assert(b.elements.get('#toast').textContent.includes('20자'));});
test('각성 출발에도 이름·결정 대사 입력 제공·덱의 전용기에 이름 표시',()=>{const b=boot();b.ui.draft.origins='time';b.ui.render();assert(b.text().includes('id="birth-stand-name"'));b.input('birth-stand-name','시곗바늘');b.input('birth-stand-line','지금 멈춘다!');b.ui.action('start');assert.equal(b.ui.race.state.stand.name,'시곗바늘');assert.equal(b.ui.race.state.stand.line,'지금 멈춘다!');b.ui.action('deck');assert(b.elements.get('#sheet-body').innerHTML.includes('시곗바늘'));assert(!b.elements.get('#sheet-body').innerHTML.includes('시곗바늘 · 발현'));});
test('경험 창에서 이름과 대사를 무료 수정·기존 히든 성장 진척과 보상 표시',()=>{const b=boot();b.ui.draft.origins='time';b.ui.action('start');const r=b.ui.race;r.state.usedEvents.push('origin_time_1');b.ui.action('relics');assert(b.elements.get('#sheet-body').innerHTML.includes('히든 전용 성장 · 멈춘 동안 놓친 것'));const cash=r.state.ch.money,tick=r.state.tick;b.document.querySelector('#edit-stand-name').value='새로운 초침';b.document.querySelector('#edit-stand-line').value='한 걸음 더!';b.ui.action('stand-save');assert.equal(r.state.stand.name,'새로운 초침');assert.equal(r.state.ch.money,cash);assert.equal(r.state.tick,tick);assert(b.text().includes('새로운 초침'));});
test('사용자 결정 대사는 전용기 첫 타격에만 말풍선으로 표시하고 HTML을 실행하지 않음',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.tick=8;r.state.mode='event';r.state.event='stand_palm';b.ui.render();b.input('awakening-stand-name','나의 별');b.input('awakening-stand-line','<b>여기서 끝낸다!</b>');b.ui.action('event:1');r.state.mode='encounter';r.state.encounter='johnny';b.ui.action('encounter:fight');const C=r.state.combat;C.P.hp=C.P.maxHp=C.E.hp=C.E.maxHp=10000;C.P.atk=300;C.E.eva=-300;C.P.hand=[b.ui.data.stands.types.rapid.cards[0]];C.ePlan=[];b.ui.action('select:0');b.ui.action('resolve');const p=r.state.playback;let guard=200;while(p.events[p.cursor].k!=='atk'&&guard--)b.step();assert(guard>0);assert(b.text().includes('&lt;b&gt;여기서 끝낸다!&lt;/b&gt;'));assert(!b.text().includes('<b>여기서 끝낸다!</b>'));assert(b.text().includes('나의 별'));const first=p.cursor;while((p.cursor===first||p.events[p.cursor].k!=='atk')&&guard--)b.step();assert(guard>0);assert(!b.text().includes('여기서 끝낸다!'));});
test('스탠드 보유 히든의 옛 공용 각성 저장은 이어하기 직후 다른 사건으로 진행',()=>{const b=boot();b.ui.draft.origins='time';b.ui.action('start');const r=b.ui.race;r.state.mode='event';r.state.event='stand_palm';r.state.tick=8;b.storage.set('sbr-race-v04',JSON.stringify(r.state));const copy=boot(b.storage);copy.ui.action('continue');assert.equal(copy.ui.race.state.tick,8);assert.notEqual(copy.ui.race.state.event,'stand_palm');assert(!copy.text().includes('id="awakening-stand-name"'));});
test('미각성 출발에는 스탠드 상태·각성 가능 안내를 노출하지 않음',()=>{for(const id of ['ranch','steel','hamon','vampire']){const b=boot();b.ui.draft.origins=id;b.ui.render();assert(!b.text().includes('미각성'));assert(!b.text().includes('초반 여정에서 각성'));b.ui.action('start');assert(!b.text().includes('stand-summary'));b.ui.action('equipment');assert(!b.elements.get('#sheet-body').innerHTML.includes('스탠드'));b.ui.action('relics');assert(!b.elements.get('#sheet-body').innerHTML.includes('스탠드'));}});

test('두 사건을 마치면 첫 구간에서 각성 선택을 표시하고 이름 입력 가능',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;for(let i=0;i<2;i++){r.state.mode='event';r.state.mode='event';r.state.event='town_clinic';b.ui.action('event:2');}assert.equal(r.state.tick,2);assert.equal(r.state.event,'stand_palm');assert(b.text().includes('id="awakening-stand-name"'));assert(b.text().includes('카드 3장을 보관함으로'));});
test('각성 보상은 기존 덱 유지·보관 수 표시·같은 덱 창에서 수동 추가와 해제',()=>{const b=boot();b.ui.action('start');const r=b.ui.race,base=r.state.ch.deck.slice();r.state.tick=2;r.state.mode='event';r.state.event='stand_palm';b.ui.action('event:0');assert.deepEqual(r.state.ch.deck,base);assert.equal(r.state.ch.side.length,3);assert(b.text().includes('덱 4'));b.ui.action('deck');assert(b.elements.get('#sheet-body').innerHTML.includes('보관 3장'));const body=b.elements.get('#sheet-body').innerHTML;assert(/data-action="insert:0"[^>]*>/.test(body));assert(!/data-action="insert:0"[^>]*disabled/.test(body));b.ui.action('insert:0');assert.equal(r.state.ch.deck.length,5);b.ui.action('remove:4');assert.deepEqual(r.state.ch.deck,base);assert.equal(r.state.ch.side.length,3);});
test('히든 덱 화면에서 기존 카드를 해제하고 추가 스탠드 카드와 교체',()=>{const b=boot();b.ui.draft.origins='vampire';b.ui.action('start');const r=b.ui.race;r.state.tick=2;r.state.mode='event';r.state.event='stand_palm';b.ui.action('event:0');b.ui.action('deck');assert(b.elements.get('#sheet-body').innerHTML.includes('4~12장'));while(r.state.ch.deck.length>4)b.ui.action('remove:0');assert.equal(r.state.ch.deck.length,4);b.ui.action('remove:0');assert.equal(r.state.ch.deck.length,4);b.ui.action('swap-pick:0');assert(!/data-action="swap-with:0"[^>]*disabled/.test(b.elements.get('#sheet-body').innerHTML));b.ui.action('swap-with:0');assert.equal(r.state.ch.deck.length,4);assert(r.state.ch.deck.some(id=>b.ui.data.cards[id].stand));});
test('스탠드 보유 히든의 수련 화면은 중간 보상과 강화된 최종 효과를 표시',()=>{const b=boot();b.ui.draft.origins='time';b.ui.action('start');const r=b.ui.race;r.state.hiddenRoute=null;r.state.tick=24;r.state.mode='event';r.state.event='origin_time_2';r.state.ch.flags.story_time_1=true;b.ui.render();assert(b.text().includes('실전 통과: 전투 시작: 호흡 +3'));r.state.tick=48;r.state.event='origin_time_3';r.state.ch.flags.story_time_2=true;r.state.ch.flags.story_time_master=true;b.ui.action('event:0');assert(r.state.items.includes('lesson_time'));b.ui.action('relics');const body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('기세 +2'));assert(body.includes('호흡 +2'));assert(body.includes('보호막 +8'));});
test('스탠드 카드를 모두 해제한 뒤 이어하기 화면에서도 자동 장착하지 않음',()=>{const b=boot();b.ui.draft.talents='recovery';b.ui.action('start');const r=b.ui.race;b.ui.action('deck');b.ui.action('insert:0');b.ui.action('remove:4');const base=r.state.ch.deck.slice();const copy=boot(new Map(b.storage));copy.ui.action('continue');assert.deepEqual(copy.ui.race.state.ch.deck,base);assert.equal(copy.ui.race.state.ch.side.length,3);assert(copy.text().includes('덱 4'));copy.ui.action('deck');assert(copy.elements.get('#sheet-body').innerHTML.includes('보관 3장'));});

test('장비 화면에서 무기·장신구 해제와 재장착·자동 저장 후 빈 슬롯 유지',()=>{const b=boot();b.ui.action('start');const r=b.ui.race,w=r.state.equipment.weapon,atk=r.state.ch.stats.atk;r.state.items.push('coat');assert(r.equipItem('coat'));const tick=r.state.tick;b.ui.action('equipment');let body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('data-action="unequip:'+w+'"'));assert(body.includes('data-action="unequip:coat"'));b.ui.action('unequip:'+w);b.ui.action('unequip:coat');assert.deepEqual(r.state.equipment,{});assert.equal(r.state.tick,tick);body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('장착 없음'));assert(body.includes('data-action="equip:'+w+'"'));b.ui.action('continue');assert.deepEqual(r.state.equipment,{});b.ui.action('equip:'+w);assert.equal(r.state.ch.stats.atk,atk);assert.equal(r.state.tick,tick);});
test('일반 적의 보상 화면은 영구 경험 박스 없이 카드와 돈만 제공',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='encounter';r.state.encounter='rough_rider';assert(r.encounter('fight'));const C=r.state.combat;C.P.atk=300;C.E.eva=-300;C.E.hp=1;C.P.hand=['sbr_basic_strike'];C.ePlan=[];assert(r.round([0]));b.ui.render();assert(b.text().includes('대결 뒤에 남은 것'));assert(b.text().includes('전투 보상 $'));assert(!b.text().includes('이번 레이스 동안 영구 적용'));assert.deepEqual(r.state.relics,[]);b.ui.action('cash-card');assert.equal(r.state.tick,1);});
test('메인 화면은 사건·선택지 한 영역과 직접 메뉴·덱 해제/추가 명시',()=>{const b=boot();b.ui.action('start');assert(b.text().includes('class="journey-body"'));assert(b.text().includes('class="direct-dock"'));b.ui.action('deck');let body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('4~12장'));b.ui.race.state.ch.side.push('sbr_basic_cut');b.ui.action('deck');body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('>추가</button>'));b.ui.action('insert:0');body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('>해제</button>'));});

test('덱·장비·경험만 하단에 두고 기록은 상단 메뉴로 이동',()=>{const b=boot();b.ui.action('start');const h=b.text().match(/<header>[\s\S]*?<\/header>/)[0],dock=b.text().match(/<footer class="direct-dock">[\s\S]*?<\/footer>/)[0];assert(h.includes('data-action="menu"'));assert(!h.includes('data-action="history"'));b.ui.action('menu');assert(b.elements.get('#sheet-body').innerHTML.includes('data-action="history"'));assert(!dock.includes('history'));for(const a of ['deck','equipment','relics'])assert(dock.includes('data-action="'+a+'"'));assert(!dock.includes('data-action="shop"'));assert(!b.text().includes('경험·장비'));});
test('경험을 13개 보유해도 장비 창 내용과 해제 버튼은 동일',()=>{const b=boot();b.ui.action('start');b.ui.action('equipment');const before=b.elements.get('#sheet-body').innerHTML,r=b.ui.race;r.state.relics=Object.keys(b.ui.data.relics);r.state.items.push('lesson_steel');b.ui.action('equipment');assert.equal(b.elements.get('#sheet-body').innerHTML,before);b.ui.action('relics');const body=b.elements.get('#sheet-body').innerHTML;for(const relic of Object.values(b.ui.data.relics))assert(body.includes(relic.n));assert(body.includes(b.ui.data.items.lesson_steel.n));assert(!body.includes('data-action="unequip:'));});
test('중복 카드 두 번째 장의 해제는 정확한 인덱스에 적용·다른 카드와 수량 보존',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.ch.deck=['sbr_basic_strike','sbr_basic_shoot','sbr_basic_strike','sbr_basic_guard','sbr_basic_cut'];r.state.ch.side=[];b.ui.action('deck');b.ui.action('remove:2');assert.deepEqual(r.state.ch.deck,['sbr_basic_strike','sbr_basic_shoot','sbr_basic_guard','sbr_basic_cut']);assert.deepEqual(r.state.ch.side,['sbr_basic_strike']);b.ui.action('insert:0');assert.equal(r.state.ch.deck.length,5);assert.equal(r.state.ch.deck.filter(id=>id==='sbr_basic_strike').length,2);});
test('사건 선택으로 행선지 결정·한 행동만 소비·새 사건과 저장 복원 유지',()=>{for(const [index,where]of [[0,'road'],[1,'explore'],[2,'town']]){const b=boot();b.ui.draft.talents='recovery';b.ui.action('start');const r=b.ui.race;r.state.tick=1;r.state.mode='event';r.state.event='junction_1';r.state.ch.money=100;r.state.ch.hp=Math.max(1,r.state.ch.hp-20);r.state.ch.stats.eva=300;r.state.bossVisits=Object.fromEntries(b.ui.data.hiddenBosses.map(x=>[x.id,1]));r.state.namedVisits=Object.fromEntries(b.ui.data.namedEncounters.map(x=>[x.id,1]));b.ui.render();assert.equal(r.state.event,'junction_1');b.ui.action('event:'+index);assert.equal(r.state.tick,2);assert.equal(r.state.mode,'event');assert(b.ui.data.events.find(e=>e.id===r.state.event).where.includes(where));const current=r.state.event,copy=boot(new Map(b.storage));copy.ui.action('continue');assert.equal(copy.ui.race.state.event,current);assert.equal(copy.ui.race.state.tick,2);assert(!copy.text().includes('<select'));}});
test('전투 연출 중 독립 장비·경험 창은 확인만 허용·보상 선공개 없음',()=>{const b=boot();b.ui.action('start');battle(b,true);const r=b.ui.race,exp=r.state.playback.before.relics.length;b.ui.action('equipment');assert.equal(b.elements.get('#sheet-title').textContent,'장비');assert(/data-action="unequip:[^"]+"[^>]*disabled/.test(b.elements.get('#sheet-body').innerHTML));b.ui.action('relics');assert(b.elements.get('#sheet-body').innerHTML.includes('대결에서 얻은 경험 '+exp));});

test('상단 밖에서도 장비 창의 보유 붕대 사용·수량과 자동 저장 즉시 갱신',()=>{
 const b=boot();b.ui.action('start');const r=b.ui.race;r.state.usedEvents.push('stand_palm','stand_echo');r.state.tick=4;r.state.mode='travel';assert(r.travel('rest'));assert(r.buy('supply_bandage'));assert(r.buy('supply_smoke'));assert(r.chooseEvent(0));r.state.ch.hp=10;b.ui.render();assert(!r.canShop());b.ui.action('equipment');assert(b.elements.get('#sheet-body').innerHTML.includes('응급 붕대 · 1개'));assert(b.elements.get('#sheet-body').innerHTML.includes('data-action="supply:bandage"'));b.ui.action('supply:bandage');assert.equal(r.state.ch.hp,28);assert.equal(r.state.economy.stock.bandage,0);assert(!b.elements.get('#sheet-body').innerHTML.includes('응급 붕대 · 1개'));assert(b.elements.get('#sheet-body').innerHTML.includes('방호 연막 · 1개'));const stored=JSON.parse(b.storage.get('sbr-race-v04'));assert.equal(stored.economy.stock.bandage,0);assert.equal(stored.ch.hp,28);assert.equal(r.state.tick,4);
});
test('상단 사건 재접속과 대화상자 닫기·재열기는 방문이나 구입 기록 초기화 없음',()=>{
 const b=boot();b.ui.action('start');const r=b.ui.race;r.state.usedEvents.push('stand_palm','stand_echo');r.state.tick=4;r.state.mode='travel';r.state.ch.money=100;b.ui.render();b.ui.action('shop');b.ui.action('buy:supply_bandage');const cash=r.state.ch.money;b.close();b.ui.action('shop');assert.equal(r.state.economy.stock.bandage,1);assert.equal(r.state.ch.money,cash);const copy=boot(new Map(b.storage));copy.ui.action('continue');assert(copy.ui.race.canShop());assert(copy.text().includes('data-action="shop"'));copy.ui.action('shop');assert(copy.elements.get('#sheet-body').innerHTML.includes('보유 1 / 3'));copy.close();copy.ui.action('event:0');assert.equal(copy.ui.race.state.tick,4);assert(!copy.ui.race.canShop());assert(!copy.text().includes('data-action="shop"'));
});


test('결과 영역에 실제 실패 판정·피해 표시·다음 선택에서는 새 결과로 교체',()=>{
 const b=boot();b.ui.action('start');assert(!b.text().includes('class="previous-outcome"'));const r=b.ui.race;r.state.mode='event';r.state.event='river';r.state.ch.stats.atk=-100;r.state.ch.money=100;const failure=b.ui.data.events.find(e=>e.id==='river').c[3].fail;b.ui.action('event:3');assert.equal(r.state.tick,1);assert.equal(r.state.previousOutcome.check.success,false);const box=b.text().match(/<aside class="previous-outcome"[\s\S]*?<\/aside>/)[0];assert(box.includes(failure.t));assert(box.includes('실패 · '));assert(box.includes('HP '));assert(box.includes('data-action="outcome"'));r.state.mode='event';r.state.event='town_clinic';b.ui.action('event:2');assert.equal(r.state.tick,2);const next=b.text().match(/<aside class="previous-outcome"[\s\S]*?<\/aside>/)[0];assert(!next.includes(failure.t));assert(!next.includes('실패 · '));assert(!b.text().includes('다음 여정을 이어 간다'));
});
test('긴 결과 전체 보기는 내용과 수치 누락 없이 표시·닫기와 재열기에 행동·상태 불변',()=>{
 const b=boot();b.ui.action('start');const r=b.ui.race;r.state.tick=1;r.state.previousOutcome={text:'긴 사건 <제목>\n'+('결과 문장 '.repeat(100))+'<img src=x onerror=alert(1)>\nHP -12 · $+35\n마지막 효과',check:{success:true,roll:78,stat:'eva',bonus:12,score:90,dc:65}};b.ui.render();const saved=JSON.stringify(r.state);b.ui.action('outcome');assert.equal(b.elements.get('#sheet-title').textContent,'직전 선택의 결과');const full=b.elements.get('#sheet-body').innerHTML;assert(full.includes('마지막 효과'));assert(full.includes('HP -12 · $+35'));assert(full.includes('성공 · 78 + 회피 12 = 90 / 목표 65'));assert(full.includes('&lt;img'));assert(!full.includes('<img'));assert.equal(JSON.stringify(r.state),saved);b.close();assert.equal(JSON.stringify(r.state),saved);b.ui.action('outcome');assert.equal(JSON.stringify(r.state),saved);assert.equal(b.elements.get('#sheet-body').innerHTML,full);
});
test('결과는 도움·덱 열기와 이어하기 뒤에도 유지·시작과 전투 연출에는 중복 노출 없음',()=>{
 const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='event';r.state.event='town_clinic';b.ui.action('event:2');const prev=structuredClone(r.state.previousOutcome);b.ui.action('help');b.close();b.ui.action('deck');b.close();assert.deepEqual(r.state.previousOutcome,prev);const copy=boot(new Map(b.storage));copy.ui.action('continue');assert.deepEqual(copy.ui.race.state.previousOutcome,prev);assert(copy.text().indexOf('class="previous-outcome"')<copy.text().indexOf('class="journey-body"'));copy.ui.action('outcome');assert(copy.elements.get('#sheet-body').innerHTML.includes(prev.text.split('\n')[1]));copy.close();battle(copy);assert(copy.ui.race.state.playback);assert(!copy.text().includes('class="previous-outcome"'));
});

test('각성·덱 전환·구매 사건의 상황 본문에는 조작·카드 지급 설명을 섞지 않음',()=>{
 const b=boot();b.ui.action('start');const r=b.ui.race;for(const e of b.ui.data.events){assert(!/보관함|버튼|덱|카드 [0-9]장/.test(e.x),e.id);for(const c of e.c)for(const r of [c.ok,c.fail].filter(Boolean))assert(!/덱|보관함|버튼|영구 효과|카드 [0-9]장/.test(r.t),e.id+' 결과');}for(const id of ['stand_palm','stand_echo','stand_last_call']){r.state.tick=2;r.state.mode='event';r.state.event=id;b.ui.render();const narrative=b.text().match(/<p class="narrative">([\s\S]*?)<\/p>/)[1];assert(!narrative.includes('보관함')&&!narrative.includes('덱'));assert(b.text().includes('class="system-guide"'));assert(b.text().includes('각성 안내 · 카드 3장 보관'));assert(b.text().indexOf('</section>')<b.text().indexOf('class="system-guide"'));assert(b.text().includes('현재 덱은 유지됩니다.'));}
});
test('1구간 상점에 미래 구간 품목 없음·구매한 장비는 목록에서 빠지고 영수증 유지',()=>{
 const b=boot();b.ui.draft.origins='time';b.ui.action('start');const r=b.ui.race;r.state.mode='travel';r.state.tick=4;r.state.ch.money=100;b.ui.render();b.ui.action('shop');b.ui.action('shop-tab:gear');const before=b.elements.get('#sheet-body').innerHTML;assert(before.includes('data-item="gear_coat"'));assert(!before.includes('balanced_harness'));assert(!before.includes('supply_stimulant'));assert(!before.includes('구간부터 구입'));b.ui.action('buy:gear_coat');const after=b.elements.get('#sheet-body').innerHTML;assert(!after.includes('data-item="gear_coat"'));assert(after.includes('구매·장착'));assert(r.state.items.includes('coat'));
});
test('희귀 거래상은 별도 사건·상품 화면·복원·상단으로 복귀하며 추가 행동 없음',()=>{
 const b=boot();b.ui.draft.origins='time';b.ui.action('start');const r=b.ui.race;r.state.mode='travel';r.state.tick=8;r.state.ch.money=1000;b.ui.render();r.state.economy.market.rareStock=['magnetic_spurs','amber_goggles'];b.ui.render();assert(b.text().includes('data-action="trader"'));b.ui.action('trader');assert.equal(r.state.event,'hidden_trader');assert(b.text().includes('천막 뒤편의 거래상'));b.ui.action('shop');assert.equal(b.elements.get('#sheet-title').textContent,'천막 뒤편의 거래상');assert(!b.elements.get('#sheet-body').innerHTML.includes('data-item="heal"'));b.ui.action('buy:rare_magnetic_spurs');assert(r.state.items.includes('magnetic_spurs'));assert(!r.state.equipment.charm);b.close();const copy=boot(new Map(b.storage));copy.ui.action('continue');assert.equal(copy.ui.race.state.event,'hidden_trader');copy.ui.action('event:0');assert.equal(copy.ui.race.state.event,'supply_caravan');assert.equal(copy.ui.race.state.tick,8);assert(copy.text().includes('data-action="trader"'));copy.ui.action('shop');assert.equal(copy.elements.get('#sheet-title').textContent,'SBR 대회 보급소');
});
test('일반 화면과 전투는 반응형 배치를 위한 상태·본문 영역을 독립하고 메뉴 중복 없음',()=>{
 const b=boot();b.ui.action('start');assert(b.text().includes('class="race-layout"'));assert(b.text().includes('class="race-sidebar"'));assert(b.text().indexOf('class="race-sidebar"')<b.text().indexOf('class="journey-body"'));assert.equal((b.text().match(/class="direct-dock"/g)||[]).length,1);battle(b);assert(b.text().includes('class="battle-layout"'));assert(b.text().includes('class="battle-overview"'));assert(b.text().includes('class="battle-controls"'));assert.equal((b.text().match(/class="combat-matchup"/g)||[]).length,1);assert.equal((b.text().match(/class="direct-dock"/g)||[]).length,1);
});

test('보스 장비는 연출 뒤 별도 보상으로 표시·카드 보관 후 수동 장착',()=>{const b=boot();b.ui.action('start');const r=b.ui.race,w=r.state.equipment.weapon;battle(b,true);b.ui.action('equipment');assert(!b.elements.get('#sheet-body').innerHTML.includes(b.ui.data.items.trophy_johnny.n));b.close();let guard=200;while(r.state.playback&&guard--)b.step();assert(guard>0);assert(b.text().includes(b.ui.data.items.trophy_johnny.n));assert.equal(r.state.equipment.weapon,w);b.ui.action('store-card');assert(r.state.items.includes('trophy_johnny'));b.ui.action('equipment');assert(b.elements.get('#sheet-body').innerHTML.includes('data-action="equip:trophy_johnny"'));b.ui.action('equip:trophy_johnny');assert.equal(r.state.equipment.charm,'trophy_johnny');});
test('히든 카드 자동 환전도 연출 중 장비를 숨기고 완료 뒤 보관',()=>{const b=boot();b.ui.draft.origins='time';b.ui.action('start');const r=b.ui.race;battle(b,true);b.ui.action('equipment');assert(!b.elements.get('#sheet-body').innerHTML.includes('trophy_johnny'));b.close();let guard=200;while(r.state.playback&&guard--)b.step();assert(guard>0);b.ui.action('equipment');assert(b.elements.get('#sheet-body').innerHTML.includes('data-action="equip:trophy_johnny"'));assert(!r.state.equipment.charm);assert.equal(r.state.tick,1);});
test('특수 무기는 현재 성장·효과 표시·이름 저장과 초기화가 무료',()=>{const b=boot();b.ui.action('start');const r=b.ui.race,id='route_ironball';r.state.items.push(id);r.state.counters.use_route_ironball=5;r.state.itemLevels[id]=1;const tick=r.state.tick,cash=r.state.ch.money;b.ui.action('equipment');let body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('전용 성장 1/2 · 공격 사용 5 / 12회'));assert(body.includes('기세 +4'));b.document.querySelector('#item-name-'+id).value='<b>나의 궤도</b>';b.ui.action('item-save:'+id);body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('&lt;b&gt;나의 궤도&lt;/b&gt;'));assert(!body.includes('<b>나의 궤도</b>'));assert.equal(r.state.tick,tick);assert.equal(r.state.ch.money,cash);const copy=boot(new Map(b.storage));copy.ui.action('continue');copy.ui.action('equipment');assert(copy.elements.get('#sheet-body').innerHTML.includes('&lt;b&gt;나의 궤도&lt;/b&gt;'));b.document.querySelector('#item-name-'+id).value='';b.ui.action('item-save:'+id);assert.equal(r.itemName(id),b.ui.data.items[id].n);});
test('기본 무기에는 성장·이름 입력 없음·미보유 장비 이름 변경 차단',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;b.ui.action('equipment');const body=b.elements.get('#sheet-body').innerHTML;assert(!body.includes('전용 성장'));assert(!body.includes('item-name-'));const saved=JSON.stringify(r.state);b.document.querySelector('#item-name-route_ironball').value='미보유';b.ui.action('item-save:route_ironball');assert.equal(JSON.stringify(r.state),saved);});
test('성장 연출 중 장비 창은 직전 단계와 횟수를 표시·완료 뒤 새 단계 반영',()=>{const b=boot();b.ui.action('start');const r=b.ui.race,id='route_ironball';r.state.items.push(id);assert(r.equipItem(id));r.state.counters.use_route_ironball=4;battle(b);assert.equal(r.state.itemLevels[id],1);b.ui.action('equipment');let body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('전용 성장 0/2 · 공격 사용 4 / 5회'));assert(!body.includes('전용 성장 1/2'));b.close();let guard=200;while(r.state.playback&&guard--)b.step();assert(guard>0);b.ui.action('equipment');body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('전용 성장 1/2 · 공격 사용 5 / 12회'));});
test('구버전 보스 장비 보완 안내·해제 상태 유지·특수 제작의 실효 표시',()=>{const b=boot();b.ui.action('start');const r=b.ui.race,old=structuredClone(r.state);delete old.lootVersion;delete old.lootClaims;old.beaten=['ringo'];old.ch.beaten=['ringo'];old.equipment={};old.mode='event';old.event='camp_meal';old.combat=null;b.storage.set('sbr-race-v04',JSON.stringify(old));const copy=boot(new Map(b.storage));copy.ui.action('continue');const q=copy.ui.race;copy.ui.action('equipment');const body=copy.elements.get('#sheet-body').innerHTML;assert(body.includes('누락 장비를 보관함에 보완'));assert(body.includes('data-action="equip:trophy_ringo"'));assert.deepEqual(q.state.equipment,{});copy.close();q.state.tick=16;q.state.mode='event';q.state.event='duelwork_2';q.state.ch.flags.duelwork_started=true;q.state.items.push('duel_plan');copy.ui.render();assert(copy.text().includes(copy.ui.data.items.route_duelgun.n));assert(copy.text().includes('$28'));});

test('보급소 상품은 부위·장비 칸·현재 장비와 교체를 표시하고 구매 뒤 갱신',()=>{const b=boot();b.ui.draft.origins='time';b.ui.action('start');const r=b.ui.race;r.state.mode='travel';r.state.tick=8;r.state.ch.money=1000;b.ui.render();b.ui.action('shop');b.ui.action('shop-tab:gear');let body=b.elements.get('#sheet-body').innerHTML;assert.equal(b.elements.get('#sheet-title').textContent,'SBR 대회 보급소');assert(body.includes('스피드왜건 석유회사'));assert(body.includes('윈체스터 총포사'));assert(body.includes('class="slot-tag">몸통'));assert(body.includes('현재: 장착 없음'));b.ui.action('buy:gear_coat');body=b.elements.get('#sheet-body').innerHTML;assert.equal(r.state.equipment.armor,'coat');assert(body.includes('이전 장비는 보관'));b.ui.action('buy:gear_riding_gloves');assert.equal(r.state.equipment.charm,'riding_gloves');assert(r.state.items.includes('coat'));b.ui.action('equipment');assert(b.elements.get('#sheet-body').innerHTML.includes('보조 장비 · 손'));});
test('희귀 거래상도 착용 부위·보관 정책 표시·구매 후 기존 장비 유지',()=>{const b=boot();b.ui.draft.origins='time';b.ui.action('start');const r=b.ui.race;r.state.mode='travel';r.state.tick=8;r.state.ch.money=1000;b.ui.render();r.state.economy.market.rareStock=['magnetic_spurs','lined_bandolier'];b.ui.action('trader');b.ui.action('shop');const body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('보조 장비 · 발'));assert(body.includes('class="slot-tag">몸통'));assert(body.includes('구입한 희귀 장비는 보관함으로 받습니다.'));b.ui.action('buy:rare_magnetic_spurs');assert(!r.state.equipment.charm);});
test('사건 인물과 무료 선택의 실제 성격 표시·상황 본문과 안내 분리',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='event';r.state.event='stephen_briefing';b.ui.render();assert(b.text().includes('스티븐 스틸 · 대회 주최자'));assert(b.text().includes('후속 사건의 단서'));r.state.event='gunfire';r.state.ch.hp-=20;b.ui.render();assert(b.text().includes('전투 발생'));assert(b.text().includes('HP +2'));assert(b.text().includes('비용 $6'));assert(b.text().includes('후속 보답'));assert(!b.text().includes('판정 없이 선택'));const narrative=b.text().match(/class="narrative">([\s\S]*?)<\/p>/)[1];assert(!narrative.includes('비용')&&!narrative.includes('HP'));});
test('구조 선택은 자금 부족 차단·선택 후 같은 사건에서는 숨김·저장 후 후속 보상',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='event';r.state.event='gunfire';r.state.ch.money=5;b.ui.render();assert(/data-action="event:2"[^>]*disabled/.test(b.text()));b.ui.action('event:2');assert.equal(r.state.tick,0);r.state.ch.money=10;b.ui.action('event:2');assert.equal(r.state.ch.money,4);r.state.mode='event';r.state.event='gunfire';b.ui.render();assert(!b.text().includes('data-action="event:2"'));const copy=boot(new Map(b.storage));copy.ui.action('continue');const q=copy.ui.race;q.state.tick=3;q.state.mode='event';q.state.event='rescued_rider_return';copy.ui.render();assert(copy.text().includes('SBR 진행요원'));assert(copy.text().includes('장비 보관 · 손때 묻은 나침반'));copy.ui.action('event:1');assert.equal(q.state.ch.money,24);assert.equal(q.state.routeResults.rescued_rider,'shared');});
test('출신 첫 장의 두 접근과 거절을 표시·단역의 기존 두 선택 유지',()=>{const b=boot();b.ui.draft.origins='steel';b.ui.action('start');const r=b.ui.race;for(const id of ['origin_steel_1','dot_khan_pace']){r.state.mode='event';r.state.event=id;r.state.relics.push('gyro');b.ui.render();const count=id==='origin_steel_1'?3:2;assert(b.text().includes('data-count="'+count+'"'));assert.equal(b.text().includes('data-action="event:2"'),count===3);}assert(b.text().includes('도트 칸 · 레이스 참가자'));});


test('원작 카드 대사는 계획 화면이 아닌 실제 첫 타격에서만 말풍선 표시',()=>{
 const b=boot();b.ui.action('start');const r=b.ui.race;r.state.tick=56;r.state.mode='encounter';r.state.encounter='johnny';b.ui.action('encounter:fight');const C=r.state.combat;C.P.hp=C.P.maxHp=C.E.hp=C.E.maxHp=10000;C.E.atk=300;C.ePlan=[r.engine.D.cards.sbr_johnny_infinite];C.P.hand=[];const line=b.ui.data.quotes.johnny.cardLines.sbr_johnny_infinite[0].text;assert(!b.text().includes(line));b.ui.action('resolve');const p=r.state.playback;let guard=200;while(!(p.events[p.cursor].k==='atk'&&p.events[p.cursor].att==='E')&&guard--)b.step();assert(guard>0);assert(b.text().includes('class="speech"'));assert(b.text().includes(line));assert(b.text().includes('터스크 ACT.4'));const first=p.cursor;while((p.cursor===first||p.events[p.cursor].k!=='atk')&&guard--)b.step();assert(guard>0);assert(!b.text().includes(line));
});
test('버프 필살기도 실제 실행 순간에 대사 표시·링고 격파 대사는 구분',()=>{
 const b=boot();b.ui.action('start');const r=b.ui.race;r.state.tick=56;r.state.mode='encounter';r.state.encounter='otherdiego';prepareEncounter(r,'otherdiego');b.ui.action('encounter:fight');const C=r.state.combat;C.P.hp=C.P.maxHp=C.E.hp=C.E.maxHp=10000;C.ePlan=[r.engine.D.cards.sbr_enemy_otherdiego];C.P.hand=[];b.ui.action('resolve');const p=r.state.playback;let guard=200;while(p.events[p.cursor].k!=='buff'&&guard--)b.step();assert(guard>0);assert(b.text().includes(b.ui.data.quotes.otherdiego.text));r.finishPlayback();r.state.encounter='ringo';r.state.mode='reward';r.state.offer='sbr_enemy_ringo';b.ui.render();assert(b.text().includes(b.ui.data.quotes.ringo.defeatedText.replaceAll("'",'&#39;')));assert(!b.text().includes(b.ui.data.quotes.ringo.text));
});
test('새 원작 희귀 인물의 조우 화면은 무명 적으로 설명하지 않음',()=>{
 const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='encounter';r.state.encounter='boomboom';r.state.message=b.ui.data.namedEncounters.find(x=>x.id==='boomboom').omen;b.ui.render();assert(b.text().includes('붐붐 일가'));assert(b.text().includes('일반 습격자보다 강한'));assert(!b.text().includes('이름 없는 상대가 길을 막고'));b.ui.action('encounter:fight');assert(b.text().includes('툼 오브 더 붐'));
});

function defeatForAchievement(b,id='johnny',tick=56){
 if(!b.ui.race.state)b.ui.action('start');const r=b.ui.race;r.state.tick=tick;r.state.mode='encounter';r.state.encounter=id;prepareEncounter(r,id);b.ui.action('encounter:fight');const C=r.state.combat;C.P.hp=C.P.maxHp=10000;C.P.atk=300;C.P.hand=['sbr_basic_shoot'];C.P.light=3;C.E.hp=1;C.E.eva=-300;C.ePlan=[];b.ui.action('select:0');b.ui.action('resolve');return r;
}
function endAchievementPlayback(b){let guard=200;while(b.ui.race.state.playback&&guard--)b.step();assert(guard>0);}
test('출생 확률표의 히든은 이름·특화·개별 확률과 속성 노출 없이 ???',()=>{
 const b=boot();b.ui.action('birth-rates');const body=b.elements.get('#sheet-body').innerHTML;for(const table of Object.values(b.ui.data.birth.tables))for(const o of table.filter(o=>o.hidden))assert(!body.includes(o.n));assert.equal((body.match(/<b>\?\?\?<\/b>/g)||[]).length,Object.values(b.ui.data.birth.tables).flat().filter(o=>o.hidden).length);assert(body.includes('목장 출신'));assert(body.includes('10%'));assert(!/[123]%/.test(body));
});
test('실제로 뽑은 히든은 확인 가능하되 결과 상세에서도 개별 확률 숨김',()=>{
 const b=boot();b.ui.draft.origins='time';b.ui.render();assert(b.text().includes(b.ui.data.starts.find(o=>o.id==='time').n));assert(!b.text().includes('히든 1%'));b.ui.action('birth-detail:origins');const body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('확률 비공개'));assert(!body.includes('뽑힐 확률 1%'));
});
test('미달성 업적은 이름·덱·조건을 숨기며 잠긴 덱 선택 불가',()=>{
 const b=boot();b.ui.action('achievements');const body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('달성 0 / 3'));assert.equal((body.match(/<b>\?\?\?<\/b>/g)||[]).length,3);for(const d of Object.values(b.ui.data.achievementDecks))assert(!body.includes(d.n));b.ui.action('achievement-deck:world');assert(!b.ui.draft.achievementDeck);assert(!b.ui.race.state);
});
test('ACT.4 승리 업적은 마지막 타격 재생 후 프로필에 저장·현재 덱 유지',()=>{
 const b=boot(),r=defeatForAchievement(b),deck=r.state.ch.deck.slice();assert(r.state.playback);assert(!b.storage.has('sbr-race-achievements-v1'));b.ui.action('achievements');assert(b.elements.get('#sheet-body').innerHTML.includes('달성 0 / 3'));b.close();endAchievementPlayback(b);assert(JSON.parse(b.storage.get('sbr-race-achievements-v1')).unlocked.tusk);assert.deepEqual(r.state.ch.deck,deck);b.ui.action('achievements');const body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('터스크 ACT.4를 사용하는 죠니 격파'));assert(body.includes('해금 덱 · 터스크 · 6장'));assert(!body.includes('data-action="achievement-deck:tusk"'));
});
test('새 출발·다시 접속 뒤 해금 덱 선택·4항목 재추첨과 덱별 출발 구성',()=>{
 const b=boot();defeatForAchievement(b);endAchievementPlayback(b);const copy=boot(new Map(b.storage));copy.ui.action('achievements');assert(copy.elements.get('#sheet-body').innerHTML.includes('data-action="achievement-deck:tusk"'));copy.ui.action('achievement-deck:tusk');assert.equal(copy.ui.draft.achievementDeck,'tusk');assert(copy.text().includes('업적 덱 · <b>터스크</b>'));const oldRolls={...copy.ui.draft.rolls};copy.ui.action('roll-birth');assert.equal(copy.ui.draft.achievementDeck,'tusk');assert.notDeepEqual(copy.ui.draft.rolls,oldRolls);copy.input('birth-stand-name','나의 송곳니');copy.ui.action('start');assert.equal(copy.ui.race.state.ch.deck.length,6);assert.equal(copy.ui.race.state.stand.name,'나의 송곳니');assert.equal(copy.ui.race.state.stand.type,'route_tusk');assert(copy.storage.has('sbr-race-achievements-v1'));copy.ui.action('reset');copy.ui.action('achievements');assert(copy.elements.get('#sheet-body').innerHTML.includes('해금 덱 · 터스크'));
});
test('해금 덱을 선택해도 기본 추첨 덱으로 되돌릴 수 있음',()=>{
 const b=boot();defeatForAchievement(b);endAchievementPlayback(b);b.ui.action('reset');b.ui.action('achievements');b.ui.action('achievement-deck:tusk');assert(b.ui.draft.achievementDeck);b.ui.action('achievements');b.ui.action('achievement-deck:random');assert(!b.ui.draft.achievementDeck);assert(!b.text().includes('업적 덱 · <b>터스크</b>'));b.ui.action('start');assert.equal(b.ui.race.state.ch.deck.length,4);
});
test('구형 격파 저장은 시작 화면에서 해금 보완·ACT.4 근거 없이 터스크 미해금',()=>{
 const b=boot();b.ui.action('start');const g=b.ui.race.state;g.beaten=['valentine','otherdiego','johnny'];g.tick=64;g.mode='travel';delete g.opponents;const saved=new Map([['sbr-race-v04',JSON.stringify(g)]]),copy=boot(saved);copy.ui.action('achievements');const body=copy.elements.get('#sheet-body').innerHTML;assert(body.includes('해금 덱 · THE WORLD'));assert(body.includes('해금 덱 · D4C'));assert(!body.includes('해금 덱 · 터스크'));assert(JSON.parse(saved.get('sbr-race-achievements-v1')).unlocked.world);
});
test('죠니의 선택된 대사는 이어하기에도 유지하고 기술별로 구분',()=>{
 const b=boot();b.ui.action('start');const r=b.ui.race;r.state.tick=56;r.state.mode='encounter';r.state.encounter='johnny';b.ui.action('encounter:fight');const C=r.state.combat;C.P.hp=C.P.maxHp=C.E.hp=C.E.maxHp=10000;C.E.atk=300;C.ePlan=[r.engine.D.cards.sbr_johnny_hole];C.P.hand=[];b.ui.action('resolve');const p=r.state.playback;let guard=200;while(!(p.events[p.cursor].att==='E'&&p.events[p.cursor].k==='atk')&&guard--)b.step();const line=p.events[p.cursor].speech.text;assert(b.text().includes(line));const copy=boot(new Map(b.storage));copy.ui.action('continue');assert(copy.text().includes(line));assert.notEqual(line,b.ui.data.quotes.johnny.cardLines.sbr_johnny_infinite[0].text);
});
function growthUI(id='tusk'){
 const proof={world:{enemy:'otherdiego'},tusk:{enemy:'johnny',formId:'act4'},d4c:{enemy:'valentine'}};
 const b=boot(new Map([['sbr-race-achievements-v1',JSON.stringify({version:1,unlocked:proof})]]));b.ui.action('achievements');b.ui.action('achievement-deck:'+id);b.ui.action('start');return b;
}
test('업적 덱 안내는 출발·전용 사건 성장을 설명하고 경험 창은 단계와 조건을 표시',()=>{
 const b=growthUI(),r=b.ui.race;assert(b.text().includes('ACT.1'));assert(b.text().includes('전용 사건으로 성장'));assert(!b.text().includes('전용기 0 / 5회'));b.ui.action('relics');let body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('전용 성장 · 터스크'));assert(body.includes('0 / 3단계'));assert(body.includes('2구간 이후 · 전용 공격 2회 이상 사용'));b.close();b.ui.action('reset');b.ui.action('achievements');body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('ACT.1로 출발 · 전용 사건을 거쳐 ACT.4까지 성장'));
});
test('성장 선택의 서사·시스템 안내 분리와 결과 박스·덱 보관 위치·재접속 유지',()=>{
 const b=growthUI(),r=b.ui.race;while(r.state.ch.deck.length>4)b.ui.action('remove:0');b.close();const stored=r.state.ch.side[0];r.state.tick=8;r.state.stand.uses=2;r.state.mode='event';r.state.event='growth_tusk_1';b.ui.render();const narrative=b.text().match(/<p class="narrative">([\s\S]*?)<\/p>/)[1];assert(!/카드|보관|장수|단계/.test(narrative));assert(b.text().includes('전용 성장 안내'));assert(b.text().includes('터스크 · ACT.2'));b.ui.action('event:0');assert.equal(r.state.stand.level,1);assert.equal(r.state.ch.deck.length,4);assert.equal(r.state.ch.side.length,3);assert.equal(b.ui.data.cards[r.state.ch.side[0]].standSkill,b.ui.data.cards[stored].standSkill);assert(b.text().includes('aria-label="사건 결과"'));assert(b.text().includes('전용 성장 · 터스크 · ACT.2'));b.ui.action('deck');assert(b.elements.get('#sheet-body').innerHTML.includes('ACT.2'));b.close();b.ui.action('relics');const body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('1 / 3단계'));assert(body.includes('적중 시 상대 취약 +1'));const copy=boot(new Map(b.storage));copy.ui.action('continue');assert.equal(copy.ui.race.state.stand.level,1);assert.equal(copy.ui.race.state.ch.deck.length,4);
});
test('저체력 성장 선택은 비활성·회복 보류는 활성으로 표시',()=>{
 const b=growthUI('d4c'),r=b.ui.race;r.state.tick=8;r.restore(structuredClone(r.state));r.state.stand.uses=2;r.state.ch.hp=5;r.state.mode='event';r.state.event='growth_d4c_1';b.ui.render();assert(b.text().includes('체력이 부족합니다.'));assert(/data-action="event:0"[^>]*disabled/.test(b.text()));assert(/data-action="event:1"[^>]*>/.test(b.text()));b.ui.action('event:0');assert.equal(r.state.stand.level,0);assert.equal(r.state.tick,8);b.ui.action('event:1');assert.equal(r.state.ch.hp,11);assert.equal(r.state.deckGrowth.stage,0);
});
test('히든 수련의 전용 기술은 돈으로 환전하지 않고 보관 안내·수동 편성을 제공',()=>{
 const b=boot();b.ui.draft.origins='sword';b.ui.action('start');const r=b.ui.race,deck=r.state.ch.deck.slice(),cash=r.state.ch.money;r.state.hiddenRoute=null;r.state.mode='event';r.state.tick=8;r.state.event='origin_sword_1';b.ui.render();assert(b.text().includes('전용 기술 보관'));b.ui.action('event:0');assert.deepEqual(r.state.ch.deck,deck);assert.equal(r.state.ch.money,cash);assert.equal(r.state.ch.side.length,1);b.ui.action('deck');const body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('보관 1장'));assert(body.includes('흔들림 없는 검격'));assert(body.includes('data-action="insert:0"'));b.ui.action('insert:0');assert.equal(r.state.ch.deck.length,deck.length+1);assert.equal(r.state.ch.side.length,0);
});
test('이전 5장 철구 저장은 편성을 보존하고 완료 수련의 빠진 기술만 보관',()=>{
 const old=structuredClone(JSON.parse(fs.readFileSync('fixtures/dedicated-v022.json')).states.steel);old.ch.flags.story_steel_1=true;old.ch.flags.story_steel_master=true;old.routeResults.origin_steel='mastered';const b=boot(new Map([['sbr-race-v04',JSON.stringify(old)]]));b.ui.action('continue');const r=b.ui.race;assert.deepEqual(r.state.ch.deck,old.ch.deck);assert.equal(r.state.ch.money,old.ch.money);assert.equal(r.state.ch.side.length,1);b.ui.action('deck');const body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('장착 5장'));assert(body.includes('회전 집중타'));assert(body.includes('보관 1장'));const copy=boot(new Map(b.storage));copy.ui.action('continue');assert.deepEqual(copy.ui.race.state.ch.side,r.state.ch.side);
});
test('출발·진행·전투 상단은 패치 내역과 메뉴 두 버튼으로 유지',()=>{
 const b=boot();
 const top=()=>b.text().match(/<header>([\s\S]*?)<\/header>/)[1];
 for(const phase of ['birth','journey','combat']){
  if(phase==='journey')b.ui.action('start');
  if(phase==='combat')battle(b);
  assert.equal((top().match(/<button /g)||[]).length,2);
  assert(top().includes('data-action="patch-notes"'));
  assert(top().includes('data-action="menu"'));
  assert.equal((top().match(/aria-haspopup="dialog"/g)||[]).length,2);
 }
});

test('출발 전 패치 모달은 최신순·현재 버전·강화 수치를 표시하고 추첨을 보존',()=>{
 const b=boot(),draft=JSON.stringify(b.ui.draft);
 assert(!b.elements.get('#sheet').open);
 b.elements.get('#sheet').scrollTop=500;b.ui.action('patch-notes');
 const body=b.elements.get('#sheet-body').innerHTML;
 assert.equal(b.elements.get('#sheet-title').textContent,'패치 내역');
 assert(b.elements.get('#sheet').open);
 assert.equal(b.elements.get('#sheet').scrollTop,0);
 assert(body.includes('현재 버전 '+b.ui.data.version));
 assert(body.indexOf('v0.24.1')<body.indexOf('v0.24.0'));
 assert(body.includes('최대 HP +24, 공격 +6, 속도 +2, 회피 +4'));
 assert.equal(JSON.stringify(b.ui.draft),draft);
 assert(!b.ui.race.state);
 b.close();assert(!b.elements.get('#sheet').open);
 assert(fs.readFileSync('dist/index.html','utf8').includes('<dialog id="sheet" aria-labelledby="sheet-title">'));
});

test('메뉴는 보조 도구만 모으고 시작 전에는 기록을 숨김·도움과 설정 연결',()=>{
 const b=boot();b.ui.action('menu');
 let body=b.elements.get('#sheet-body').innerHTML;
 assert.equal(b.elements.get('#sheet-title').textContent,'메뉴');
 for(const a of ['achievements','settings','help','about'])assert(body.includes('data-action="'+a+'"'));
 assert(!body.includes('data-action="history"'));
 for(const a of ['settings','help','about','achievements']){b.ui.action(a);assert.notEqual(b.elements.get('#sheet-title').textContent,'메뉴');b.ui.action('menu');}
 b.close();b.ui.action('start');b.ui.action('menu');
 body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('data-action="history"'));
 for(const a of ['deck','equipment','relics'])assert(!body.includes('data-action="'+a+'"'));
 b.ui.action('history');assert.equal(b.elements.get('#sheet-title').textContent,'나의 여정');
});

test('패치와 메뉴를 열고 닫아도 행동·체력·자금·덱·저장 기록은 동일',()=>{
 const b=boot();b.ui.action('start');
 const before=JSON.stringify(b.ui.race.state),saved=b.storage.get('sbr-race-v04');
 b.ui.action('patch-notes');b.ui.action('menu');b.ui.action('patch-notes');b.close();
 assert.equal(JSON.stringify(b.ui.race.state),before);
 assert.equal(b.storage.get('sbr-race-v04'),saved);
});

test('전투 중 패치와 메뉴는 연출을 멈추고 닫으면 같은 위치에서 재개',()=>{
 const b=boot();b.ui.action('start');battle(b);
 const before=JSON.stringify(b.ui.race.state),cursor=b.ui.race.state.playback.cursor;
 assert.equal(b.timers.size,1);b.ui.action('patch-notes');assert.equal(b.timers.size,0);
 b.ui.action('menu');assert.equal(b.timers.size,0);
 assert.equal(b.ui.race.state.playback.cursor,cursor);
 assert.equal(JSON.stringify(b.ui.race.state),before);
 b.close();assert.equal(b.timers.size,1);
 assert.equal(b.ui.race.state.playback.cursor,cursor);
 b.step();assert(b.ui.race.state.playback.phase!=='announce'||b.ui.race.state.playback.cursor!==cursor);
});

test('자동 강화는 손패 이름·명중·피해·주사위와 실제 전투 연출에 일치',()=>{
 const b=boot();b.ui.action('start');const r=b.ui.race;r.state.tick=48;r.restore(r.state);
 r.state.mode='encounter';r.state.encounter='gyro';b.ui.action('encounter:fight');
 const C=r.state.combat;C.P.hand=['sbr_basic_shoot'];C.P.atk=300;C.P.hp=C.P.maxHp=C.E.hp=C.E.maxHp=10000;C.E.eva=-300;C.ePlan=[];b.ui.render();
 assert(b.text().includes('원거리 견제 +3'));assert(b.text().includes('1타 × 2d6 +5 · 명중 +30'));
 b.ui.action('select:0');b.ui.action('resolve');
 const p=r.state.playback;assert.equal(p.before.P.cg.tier,3);const ev=p.events.find(e=>e.k==='atk'&&e.att==='P');assert.equal(ev.rolls.length,2);assert.equal(ev.b,5);
});

test('덱 창의 장착·보관 카드에 현재 강화 수치 표시·카드 이동해도 중첩 없음',()=>{
 const b=boot();b.ui.action('start');const r=b.ui.race;r.state.tick=32;r.restore(r.state);r.state.ch.side.push('sbr_basic_shoot');
 b.ui.action('deck');let body=b.elements.get('#sheet-body').innerHTML;
 assert(body.includes('공격 카드 +2 · 명중 +10 · 적중 피해 +3 · 피해 주사위 +1개'));
 assert(body.includes('원거리 견제 +2'));assert(body.includes('1타 × 2d6 +3 · 명중 +25'));
 const index=r.state.ch.side.length-1;b.ui.action('insert:'+index);body=b.elements.get('#sheet-body').innerHTML;
 assert(body.includes('1타 × 2d6 +3 · 명중 +25'));assert(!body.includes('원거리 견제 +2 +2'));assert.equal(b.ui.data.cards.sbr_basic_shoot.b,0);
});

test('이전 연출 저장의 덱은 소급 강화 표시 없이 보존·새 패치 내역은 첫 항목',()=>{
 const fixture=JSON.parse(fs.readFileSync('fixtures/player-growth-v0241.json','utf8')).playback;
 const b=boot(new Map([['sbr-race-v04',JSON.stringify(fixture)]]));b.ui.action('continue');b.ui.action('deck');
 assert(!b.elements.get('#sheet-body').innerHTML.includes('공격 카드 +2'));
 b.ui.action('patch-notes');const body=b.elements.get('#sheet-body').innerHTML;
 assert(body.indexOf('v0.25.0')<body.indexOf('v0.24.1'));assert(body.includes('구간 통과 보상을 최대 HP +8'));
 assert.deepEqual(b.ui.race.state.playback,fixture.playback);
});

test('상점은 물자·장비·정비를 구분하고 구매 뒤에도 선택 분류와 결과를 유지',()=>{
 const b=boot();b.ui.action('start');const r=b.ui.race;r.state.usedEvents.push('stand_palm','stand_echo');r.state.tick=8;r.state.mode='travel';r.state.ch.money=1000;b.ui.render();b.ui.action('shop');
 let body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('data-item="supply_bandage"'));assert(!body.includes('data-item="gear_'));
 const tick=r.state.tick;b.ui.action('shop-tab:gear');body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('data-item="gear_coat"'));assert(!body.includes('data-item="supply_bandage"'));assert(body.includes('slot-tag">무기'));
 b.ui.action('buy:gear_coat');body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('shop-result'));assert(body.includes('data-action="shop-tab:gear" class="active"'));assert.equal(r.state.tick,tick);assert.equal(r.state.equipment.armor,'coat');
 b.ui.action('shop-tab:service');body=b.elements.get('#sheet-body').innerHTML;assert(body.includes('data-item="tune"'));assert(!body.includes('data-item="gear_'));
});

test('테마와 전투 연출 설정은 서로 보존되고 재접속·새 출발에도 적용',()=>{
 const b=boot();assert.equal(b.document.documentElement.dataset.theme,'dusk');b.ui.action('settings');b.ui.action('theme:paper');assert.equal(b.document.documentElement.dataset.theme,'paper');
 b.ui.action('speed:fast');let settings=JSON.parse(b.storage.get('sbr-race-settings'));assert.deepEqual(settings,{combat:'fast',theme:'paper'});
 b.ui.action('theme:ink');settings=JSON.parse(b.storage.get('sbr-race-settings'));assert.deepEqual(settings,{combat:'fast',theme:'ink'});
 const copy=boot(new Map(b.storage));assert.equal(copy.document.documentElement.dataset.theme,'ink');copy.ui.action('settings');assert(copy.elements.get('#sheet-body').innerHTML.includes('data-action="speed:fast" class="primary"'));
 copy.close();copy.ui.action('start');copy.ui.action('reset');assert.equal(copy.document.documentElement.dataset.theme,'ink');
});

test('연출 중 테마 전환은 전투·덱·판정에 영향을 주지 않고 닫으면 재개',()=>{
 const b=boot();b.ui.action('start');battle(b);const before=JSON.stringify(b.ui.race.state);b.ui.action('settings');b.ui.action('theme:paper');assert.equal(b.timers.size,0);assert.equal(JSON.stringify(b.ui.race.state),before);b.close();assert.equal(b.timers.size,1);
});

test('결승 직전 결과·순위·연장 선택과 완결의 개인 기록을 표시',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.tick=71;r.state.mode='event';r.state.event='camp_meal';b.ui.action('event:0');assert.equal(r.state.mode,'finish-gate');assert(b.text().includes('지금 완주하면'));assert(b.text().includes('직전 결과'));for(const n of [1,4,8])assert(b.text().includes('extend-race:'+n));b.ui.action('finish-race');assert(b.text().includes('최종 순위'));assert(b.text().includes('길 위에 남긴 이름'));assert(b.text().includes('마지막 덱'));assert(!b.text().includes('extend-race:'));});
test('화면 연장 선택은 저장하고 선택한 추가 행동 뒤 다시 완주를 선택',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.tick=72;r.state.mode='finish-gate';b.ui.render();b.ui.action('extend-race:1');assert.equal(r.state.finishAt,73);assert.equal(JSON.parse(b.storage.get('sbr-race-v04')).finishAt,73);if(r.state.mode!=='finish-gate'){r.state.mode='event';r.state.event='camp_meal';b.ui.action('event:0');}assert.equal(r.state.mode,'finish-gate');assert(b.text().includes('2위'));});
test('실제 전투 화면에 도주 버튼·HP 보존·승리 보상 없음 안내',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='encounter';r.state.encounter='ringo';b.ui.action('encounter:fight');assert(b.text().includes('data-action="flee"'));assert(b.text().includes('승리 보상 없음'));r.state.combat.P.hp=5;const before=r.state.beaten.slice();b.ui.action('flee');assert(!r.state.combat);assert.equal(r.state.escapes,1);assert.deepEqual(r.state.beaten,before);assert(b.text().includes('도망치는 거다'));});
test('대사 재생 중에는 도주로 이미 계산된 결과를 취소하지 않음',()=>{const b=boot();b.ui.action('start');battle(b);assert(b.ui.race.state.playback);const before=JSON.stringify(b.ui.race.state);b.ui.action('flee');assert.equal(JSON.stringify(b.ui.race.state),before);assert(!b.text().includes('data-action="flee"'));});
test('도주 직후 화면에 남은 3행동을 안내하고 실제 여정 선택으로 감소',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='encounter';r.state.encounter='ringo';b.ui.action('encounter:fight');b.ui.action('flee');assert(b.text().includes('남은 3행동 동안 적 조우 없음'));r.state.mode='event';r.state.event='camp_meal';b.ui.render();b.ui.action('event:0');assert.equal(r.encounterGrace(),2);assert(b.text().includes('남은 2행동 동안 적 조우 없음'));});
test('무료 거절 선택의 표시와 저장·진행 행동 소비가 일치',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='event';r.state.event='town_merchant';const tick=r.state.tick;b.ui.render();assert(b.text().includes('행동 소모 없음'));b.ui.action('event:2');assert.equal(r.state.tick,tick);assert.equal(JSON.parse(b.storage.get('sbr-race-v04')).tick,tick);});
test('삭제한 단서 사건 저장은 행동 소모 없이 여정으로 복귀',()=>{const b=boot();b.ui.action('start');const r=b.ui.race;r.state.mode='event';r.state.event='clue_gyro';const tick=r.state.tick;assert(r.restore(r.state));assert.equal(r.state.mode,'travel');b.ui.render();assert.equal(r.state.tick,tick);assert.notEqual(r.state.event,'clue_gyro');assert(!b.text().includes('현상금 쪽지를 쥔 추적자'));});
